entries[102145] = { ["name"] = "Chi-Chi, Küken von Chi-Ji", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nRechtsklicken, um die süße Knuddelversion von Chi-Ji zu beschwören und freizugeben.\n80 ( 80)" }
entries[102146] = { ["name"] = "Zao, Kalb von Niuzao", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nRechtsklicken, um die süße Knuddelversion von Niuzao zu beschwören und freizugeben.\n80 ( 80)" }
entries[102147] = { ["name"] = "Yu'la, Junges von Yu'lon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nRechtsklicken, um die süße Knuddelversion von Yu'lon zu beschwören und freizugeben.\n80 ( 80)" }
