entries[102156] = { ["name"] = "Armband der Donnerfürsten", ["text"] = "Questgegenstand\n\"Grobe, aber aufschlussreiche Illustrationen der vom Hersteller dieses Armbands favorisierten Jagdtaktiken zieren das Leder.\"" }
entries[102215] = { ["name"] = "Bräuschüssel", ["text"] = "Questgegenstand\nBenutzen: Benutzt diese Schale, um Schlücke Gebräus vom Großen Rad in der Brauerei Sturmbräu zu schöpfen." }
entries[102218] = { ["name"] = "Geist des Krieges", ["text"] = "Handwerksmaterial\n\"Ein begabter Handwerker könnte damit Material der Schöpfung herstellen.\"" }
entries[102225] = { ["name"] = "Rolos Rätsel", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Die Zeit ist an diesem alten und zerfledderten Pergament alles andere als spurlos vorbeigegangen.\"" }
entries[102245] = { ["name"] = "Qian-Le, Mut von Niuzao", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRücken\n3 Rüstung\n+1 Beweglichkeit\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\n+ 2 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 2.\n\nPrismatischer Sockel\nSockelbonus: + 3 Ausdauer\nAnlegen: Die Ausdauer Niuzaos absorbiert bis zu 0 des Schadens eines Angriffs, der Euch normalerweise umbringen würde, vollständig. Dieser Effekt hat eine Abklingzeit von 2 Min. Wirkt nicht bei Charakteren, die über keine Tankspezialisierung verfügen." }
entries[102246] = { ["name"] = "Xing-Ho, Atem von Yu'lon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRücken\n3 Rüstung\n+1 Intelligenz\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nPrismatischer Sockel\nSockelbonus: + 2 Intelligenz\nAnlegen: Eure Schadenszauber haben eine Chance, Euch mit der Essenz von Yu'lon zu erfüllen, wodurch Ihr Jadedrachenfeuer auf das Ziel schleudert, was im Verlauf von 4 Sek. (200% der Zaubermacht) Schaden verursacht. Dieser Schaden wirkt sich auch auf bis zu 4 weitere Gegner in der Nähe des brennenden Ziels aus. (Ungefähr 2.61 Auslösungen pro Minute)" }
entries[102247] = { ["name"] = "Jina-Kang, Güte von Chi-Ji", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRücken\n3 Rüstung\n+1 Intelligenz\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\n+ 2 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 2.\n\nPrismatischer Sockel\nSockelbonus: + 2 Intelligenz\nAnlegen: Eure hilfreichen Zauber haben eine Chance, Euch den Geist von Chi-Ji zu verleihen, der 10 Sek. lang sämtliche Heilung um 5% erhöht und Eure überschüssige Heilung auf bis zu 5 verletzte Verbündete in der Nähe umverteilt. (Ungefähr 0.58 Auslösungen pro Minute)" }
entries[102248] = { ["name"] = "Fen-Yu, Zorn von Xuen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRücken\n3 Rüstung\n+1 Beweglichkeit\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nPrismatischer Sockel\nSockelbonus: + 2 Beweglichkeit\nAnlegen: Eure erfolgreichen Angriffe haben eine Chance, einen Rausch von Xuen auszulösen, der bis zu 5 Gegnern vor Euch 3 Sek. lang alle 0.3 Sek. 7 Schaden zufügt. (Ungefähr 1.74 Auslösungen pro Minute)" }
entries[102249] = { ["name"] = "Gong-Lu, Stärke von Xuen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRücken\n3 Rüstung\n+1 Stärke\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nPrismatischer Sockel\nSockelbonus: + 2 Stärke\nAnlegen: Eure erfolgreichen Angriffe haben eine Chance, einen Rausch von Xuen auszulösen, der bis zu 5 Gegnern vor Euch 3 Sek. lang alle 0.3 Sek. 7 Schaden zufügt. (Ungefähr 1.74 Auslösungen pro Minute)" }
entries[102250] = { ["name"] = "Qian-Ying, Kraft von Niuzao", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRücken\n3 Rüstung\n+1 Stärke\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\n+ 2 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 2.\n\nPrismatischer Sockel\nSockelbonus: + 3 Ausdauer\nAnlegen: Die Ausdauer Niuzaos absorbiert bis zu 0 des Schadens eines Angriffs, der Euch normalerweise umbringen würde, vollständig. Dieser Effekt hat eine Abklingzeit von 2 Min. Wirkt nicht bei Charakteren, die über keine Tankspezialisierung verfügen." }
