entries[102463] = { ["name"] = "Eid des Feuerwächters", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verwandelt Euch in einen Feuerwächter von Ordos. Wenn Ihr in diesem Zustand andere Spielercharaktere tötet, besteht eine Chance, blutige Münzen zu erhalten. (10 Min Abklingzeit)\n\"Feuerwächter von Ordos tragen die Asche ihrer Opfer in einem besonderen Beutel mit sich herum, in dem sie weiterglüht.\"" }
