entries[102467] = { ["name"] = "Rauchbrenner der ewigen Pein", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Opfert 90% Eurer maximalen Gesundheit, um ein Abgesandter von Ordos zu werden. Während Ihr verwandelt seid, seid Ihr allen Spielercharakteren feindlich gesinnt und das Töten anderer Spielercharaktere gewährt blutige Münzen. Kann nur auf der Zeitlosen Insel verwendet werden und markiert Euch für den PvP-Kampf. (1 Stunde Abklingzeit)\n\"Ein rituelles Opfer ist erforderlich, um ein Anhänger von Ordos zu werden.\"" }
